      <PreviewTab>
        <Box position="relative" className="demo-container" h={500} overflow="hidden">
          <DotGrid
            dotSize={dotSize}
            gap={gap}
            baseColor={baseColor}
            activeColor={activeColor}
            proximity={proximity}
            shockRadius={shockRadius}
            shockStrength={shockStrength}
            resistance={resistance}
            returnDuration={returnDuration}
          />
        </Box>

