            <Input
              type="color"
              value={baseColor}
              onChange={(e) => { setBaseColor(e.target.value); }}
              width="50px"
            />
          </Flex>
          <Flex alignItems="center" mb={4}>
            <Text fontSize="sm" mr={2}>Active Color</Text>
            <Input
              type="color"
              value={activeColor}
              onChange={(e) => { setActiveColor(e.target.value); }}
              width="50px"
            />
          </Flex>
