    },
    {
      name: "smooth",
      type: "boolean",
      default: "true",
      description: "When true, smoothens the animation of the letters for a more subtle feel."
    }
  ];

  return (
    <TabbedLayout>
      <PreviewTab>
        <Box position="relative" className="demo-container" h={500} overflow="hidden" p={0}>
