            color="#fff"
            h={8}
            onClick={() => {
              setColors([randomHex(), randomHex(), randomHex()])
              forceRerender();
            }}
          >
            Randomize Colors
          </Button>

          <PreviewSlider
            min={0}
            max={100}
            title="Glitch Speed"
            step={5}
            value={speed}
            onChange={(val) => {
              setSpeed(val);
            }}
          />

          <PreviewSwitch
            title="Smooth Animation"
            isChecked={smooth}
            onChange={(checked) => {
              setSmooth(checked);
              forceRerender();
            }}
          />

          <PreviewSwitch
            title="Show Center Vignette"
            isChecked={showCenterVignette}
            onChange={(checked) => {
              setShowCenterVignette(checked);
              forceRerender();
            }}
          />

          <PreviewSwitch
            title="Show Outer Vignette"
            isChecked={showOuterVignette}
            onChange={(checked) => {
              setShowOuterVignette(checked);
              forceRerender();
            }}
          />
        </Customize>

        <PropTable data={propData} />
      </PreviewTab>

      <CodeTab>
        <CodeExample codeObject={letterGlitch} />
      </CodeTab>

      <CliTab>
        <CliInstallation {...letterGlitch} />
      </CliTab>
    </TabbedLayout>
  );
};

export default LetterGlitchDemo;

