                max={1}
                width={50}
                step={0.1}
                value={baseColor[0]}
                title="Red"
                onChange={(val) => {
                  setBaseColor(prev => {
                    const newColors = [...prev];
                    newColors[0] = val;
                    return newColors;
                  });
                }}
              />
            </Flex>

            <Flex gap={4} align="center" mt={2} background="#170D27" px={4} borderRadius={16} position="relative">
              <PreviewSlider
                min={0}
                max={1}
                width={50}
                step={0.1}
                value={baseColor[1]}
                title="Green"
                onChange={(val) => {
                  setBaseColor(prev => {
                    const newColors = [...prev];
                    newColors[1] = val;
                    return newColors;
                  });
                }}
              />
            </Flex>

            <Flex gap={4} align="center" mt={2} background="#170D27" px={4} borderRadius={16} position="relative">
              <PreviewSlider
                min={0}
                max={1}
                width={50}
                step={0.1}
                value={baseColor[2]}
                title="Blue"
                onChange={(val) => {
                  setBaseColor(prev => {
                    const newColors = [...prev];
                    newColors[2] = val;
                    return newColors;
                  });
                }}
              />
            </Flex>
          </Flex>

          <PreviewSlider
            min={0}
            title="Speed"
            max={5}
            step={0.01}
            value={speed}
            onChange={(val) => {
              setSpeed(val);
            }}
          />

          <PreviewSlider
            min={0.1}
            title="Amplitude"
            max={1}
            step={0.01}
            value={amplitude}
            onChange={(val) => {
              setAmplitude(val);
            }}
          />

          <PreviewSwitch
            title="Enable Interaction"
            isChecked={interactive}
            onChange={(checked) => {
              setInteractive(checked);
            }}
          />
        </Customize>

        <PropTable data={propData} />
        <Dependencies dependencyList={['ogl']} />
      </PreviewTab>

      <CodeTab>
        <CodeExample codeObject={liquidChrome} />
      </CodeTab>

      <CliTab>
        <CliInstallation {...liquidChrome} />
      </CliTab>
    </TabbedLayout>
  );
};

export default LiquidChromeDemo;

