            min={0.1}
            max={2}
            step={0.1}
            value={circleEdge}
            onChange={setCircleEdge}
          />
        </Customize>

        <PropTable data={propData} />
        <Dependencies dependencyList={['three']} />
      </PreviewTab>

      <CodeTab>
        <CodeExample codeObject={shapeBlur} />
      </CodeTab>

      <CliTab>
